mapper.select:
SELECT DATE_FORMAT(sr.record_date, '%Y-%m') AS record_month, COALESCE(SUM(CASE WHEN sr.type = 'INCOME' THEN sr.amount ELSE 0 END), 0) AS income, COALESCE(SUM(CASE WHEN sr.type = 'EXPENSE' THEN sr.amount ELSE 0 END), 0) AS expense, COALESCE(SUM(CASE WHEN sr.type = 'SAVING' THEN sr.amount ELSE 0 END), 0) AS saving FROM service_record sr WHERE sr.user_id IN
#{userId}
AND sr.record_date BETWEEN #{startDate} AND #{endDate} GROUP BY DATE_FORMAT(sr.record_date, '%Y-%m') ORDER BY record_month
